import React, { useState, useEffect, useRef, useCallback } from 'react';
import axios from 'axios';
import io from 'socket.io-client';
import './App.css';

// Server URLs
const API_BASE_URL = '/api';
// Use explicit hostname for Socket.io to avoid connection issues
const SOCKET_URL = window.location.hostname === 'localhost' ? 'http://localhost:3001' : window.location.origin;

// Placeholder Google logo image (base64 encoded small Google logo)
const PLACEHOLDER_IMAGE = 'data:image/png;base64,';

function App() {
    const [sessionId, setSessionId] = useState(null);
    const [inputValue, setInputValue] = useState('');
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [browserImage, setBrowserImage] = useState(PLACEHOLDER_IMAGE); // Set initial placeholder image
    const [previewVisible, setPreviewVisible] = useState(true);
    // Add state for status messages
    const [statusMessages, setStatusMessages] = useState([{
        type: 'info',
        text: 'Test starting...',
        time: new Date().toLocaleTimeString()
    }]);
    // Add state for streaming
    const [streaming, setStreaming] = useState(false);
    const [streamStatus, setStreamStatus] = useState('waiting');
    const socketRef = useRef(null);
    const eventSourceRef = useRef(null);
    const messagesEndRef = useRef(null);
    // Add state for showing technical messages
    const [showTechnicalMessages, setShowTechnicalMessages] = useState(true);

    // Toggle display of technical messages
    const toggleTechnicalMessages = () => {
        setShowTechnicalMessages(!showTechnicalMessages);
    };

    // Helper function to add status messages with a timestamp
    const addStatusMessage = useCallback((type, text) => {
        const now = new Date();
        const timeString = now.toLocaleTimeString();
        setStatusMessages(prev => {
            // Keep only the most recent 10 messages
            const newMessages = [...prev, { type, text, time: timeString }];
            if (newMessages.length > 10) {
                return newMessages.slice(newMessages.length - 10);
            }
            return newMessages;
        });
    }, []);

    // Helper to determine status type classes
    const getStatusType = (event) => {
        switch (event) {
            case 'error': return 'error';
            case 'thinking': return 'processing';
            case 'user-message': return 'user';
            case 'ai-response': return 'assistant';
            case 'tool-call': return 'tool';
            case 'response-complete': return 'success';
            case 'warning': return 'warning';
            case 'reconnecting': return 'reconnecting';
            default: return 'info';
        }
    };

    // Initialize socket connection
    const initializeSocket = useCallback(() => {
        if (socketRef.current) return;

        console.log(`Initializing socket connection to ${SOCKET_URL}...`);

        try {
            // Use simple configuration for better backward compatibility
            socketRef.current = io(SOCKET_URL, {
                path: '/socket.io/',
                transports: ['polling'],
                upgrade: false,
                reconnection: true,
                forceNew: true
            });

            // Add error event handlers before connecting
            socketRef.current.on('connect_error', (error) => {
                console.error('Socket connection error:', error);
                addStatusMessage('error', `Connection error: ${error.message}`);

                // Fallback to HTTP API if Socket.io fails repeatedly
                if (sessionId) {
                    fetchMessagesDirectly();
                }
            });

            // Connection event handlers
            socketRef.current.on('connect', () => {
                console.log('Socket connected!', socketRef.current.id);
                addStatusMessage('success', `Connected to server (${socketRef.current.id})`);

                // Join session room if we have a sessionId
                if (sessionId) {
                    console.log(`Joining session room: ${sessionId}`);
                    socketRef.current.emit('join-session', sessionId);
                }
            });

            // Session events
            socketRef.current.on('session-joined', (data) => {
                console.log('Joined session room:', data);
                addStatusMessage('system', `Joined session: ${data.sessionId}`);
            });

            // Message events - improved handling for completion
            socketRef.current.on('message-update', (data) => {
                if (data.sessionId === sessionId && data.message) {
                    console.log('Processing message update:', data.message.role);

                    setMessages(prevMessages => {
                        // For assistant messages, update the existing one if found
                        if (data.message.role === 'assistant') {
                            const lastAssistantIndex = findLastIndex(prevMessages, m => m.role === 'assistant');

                            if (lastAssistantIndex >= 0) {
                                const newMessages = [...prevMessages];
                                newMessages[lastAssistantIndex] = {
                                    ...newMessages[lastAssistantIndex],
                                    content: data.message.content || '',
                                    tool_calls: data.message.tool_calls,
                                    finish_reason: data.message.finish_reason
                                };
                                return newMessages;
                            }
                        }

                        // For other messages or if no assistant message found, add new
                        return [...prevMessages, data.message];
                    });

                    // If this is a complete response, update loading state
                    if (data.isComplete || data.message.finish_reason === 'stop') {
                        console.log('Response complete, ending loading state');
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                    }
                }
            });

            // Status updates from server
            socketRef.current.on('status-update', (data) => {
                console.log('Status update:', data);
                addStatusMessage(getStatusType(data.event), data.message);

                // Update loading state based on status
                if (data.event === 'thinking') {
                    setLoading(true);
                } else if (data.event === 'response-complete') {
                    setLoading(false);
                }
            });

            // Error handling
            socketRef.current.on('chat-error', (data) => {
                console.error('Chat error:', data);
                setError(data.error || 'Unknown error');
                setLoading(false);
                addStatusMessage('error', `Error: ${data.error || 'Unknown error'}`);
            });

            // Disconnect handling
            socketRef.current.on('disconnect', (reason) => {
                console.log(`Socket disconnected: ${reason}`);
                addStatusMessage('system', `Disconnected: ${reason}`);

                // If we're still loading when disconnected, try to recover
                if (loading && sessionId) {
                    fetchMessagesDirectly();
                }
            });

            // Stream status updates
            socketRef.current.on('stream-status', (data) => {
                console.log('Stream status update:', data);
                setStreamStatus(data.status);
                addStatusMessage(
                    data.status === 'error' ? 'error' : 'stream',
                    data.message || `Stream ${data.status}`
                );
            });

            // Setup periodic health check
            const healthCheckInterval = setInterval(() => {
                if (socketRef.current && socketRef.current.connected) {
                    socketRef.current.emit('health-check', { timestamp: Date.now() });
                }
            }, 30000);

            // Return cleanup function
            return () => {
                clearInterval(healthCheckInterval);
                if (socketRef.current) {
                    socketRef.current.disconnect();
                    socketRef.current = null;
                }
            };
        } catch (error) {
            console.error('Error starting socket connection:', error);
            addStatusMessage('error', `Error starting socket connection: ${error.message}`);
            setLoading(false);
            setStreamStatus('error');
        }
    }, [sessionId, loading, addStatusMessage]);

    // Function to fetch messages directly from API as fallback
    const fetchMessagesDirectly = useCallback(() => {
        if (!sessionId) return;

        console.log('Fetching messages directly via API...');
        const apiUrl = getApiUrl(`/messages/${sessionId}?_t=${Date.now()}`);

        axios.get(apiUrl)
            .then(response => {
                if (response.data.success && response.data.messages) {
                    setMessages(response.data.messages);

                    // Check if response is complete to update loading state
                    const hasAssistantResponse = response.data.messages.some(m =>
                        m.role === 'assistant' && m.finish_reason === 'stop'
                    );

                    if (hasAssistantResponse) {
                        setLoading(false);
                        addStatusMessage('success', 'Response complete');
                    }
                }
            })
            .catch(err => {
                console.error('Error fetching messages:', err);
                addStatusMessage('error', `Failed to fetch messages: ${err.message}`);
            });
    }, [sessionId, addStatusMessage]);

    // Helper to find the last index of a message matching a condition
    const findLastIndex = (array, predicate) => {
        for (let i = array.length - 1; i >= 0; i--) {
            if (predicate(array[i])) return i;
        }
        return -1;
    };

    // Initialize session when component mounts
    useEffect(() => {
        const initSession = async () => {
            try {
                console.log("Initializing session...");
                let response;
                let usedDirectConnection = false;

                // Try direct connection first
                try {
                    console.log("Trying direct connection to server first...");
                    response = await axios.post('http://localhost:3001/session');
                    usedDirectConnection = true;
                    addStatusMessage('info', 'Using direct connection to server');
                    // Mark that we should use direct connection for future requests
                    window.USE_DIRECT_API = true;
                } catch (directErr) {
                    console.error("Direct connection failed, trying through proxy:", directErr);
                    addStatusMessage('warning', 'Direct connection failed, trying through proxy');
                    response = await axios.post(`${API_BASE_URL}/session`);
                }

                if (response.data.success) {
                    const newSessionId = response.data.sessionId;
                    setSessionId(newSessionId);
                    addStatusMessage('system', `Session initialized${usedDirectConnection ? ' via direct connection' : ''}: ${newSessionId}`);

                    // Initialize tools using the same connection method that worked
                    const toolsUrl = usedDirectConnection || window.USE_DIRECT_API
                        ? 'http://localhost:3001/init'
                        : `${API_BASE_URL}/init`;

                    await axios.get(toolsUrl)
                        .then(res => {
                            if (res.data.toolCount) {
                                addStatusMessage('system', `Initialized ${res.data.toolCount} tools`);
                            }
                        })
                        .catch(err => {
                            addStatusMessage('error', `Error initializing tools: ${err.message}`);
                        });

                    // Take an initial screenshot
                    requestScreenshot();

                    // Auto-start streaming after a short delay
                    setTimeout(() => {
                        addStatusMessage('info', 'Auto-starting browser stream...');
                        startStream();
                    }, 1500);
                } else {
                    setError(`Error initializing session: ${response.data.error}`);
                }
            } catch (err) {
                console.error("Session initialization error:", err);
                setError(`Failed to initialize session: ${err.message}`);
                // Try direct API call as a last resort
                tryDirectApiCall();
            }
        };

        initSession();
    }, []);

    // Initialize socket connection when sessionId changes
    useEffect(() => {
        if (sessionId) {
            initializeSocket();
        }

        return () => {
            if (socketRef.current) {
                socketRef.current.disconnect();
                socketRef.current = null;
            }
        };
    }, [sessionId, initializeSocket]);

    // Scroll to bottom when messages change
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    // Handle sending a message
    const handleSendMessage = async (e) => {
        e.preventDefault();

        if (!inputValue.trim() || !sessionId) {
            if (!sessionId) setError('Session not initialized. Please try again.');
            return;
        }

        // Add user message to state immediately
        const userMessage = { role: 'user', content: inputValue };
        setMessages([...messages, userMessage]);
        setInputValue('');
        setLoading(true);
        setError(null);

        try {
            // Emit message through socket for faster processing
            if (socketRef.current && socketRef.current.connected) {
                socketRef.current.emit('chat-message', {
                    sessionId,
                    message: inputValue,
                    timestamp: Date.now()
                });

                // Take a screenshot after sending message to show current state
                requestScreenshot();

                // Start the stream if not already running
                if (!streaming) {
                    startStream();
                }
            } else {
                // Fallback to HTTP if socket not connected
                const apiUrl = getApiUrl(`/chat/${sessionId}`);
                const response = await axios.post(apiUrl, {
                    message: inputValue
                });

                if (!response.data.success) {
                    throw new Error(response.data.error || 'Unknown error');
                }
            }
        } catch (err) {
            console.error('Error sending message:', err);
            setError(`Error: ${err.message}`);
            setLoading(false);
        }
    };

    // Start browser stream
    const startStream = () => {
        if (eventSourceRef.current) {
            stopStream();
            setTimeout(initStream, 500);
            return;
        }

        initStream();
    };

    // Initialize stream connection
    const initStream = () => {
        try {
            setStreaming(true);
            setStreamStatus('connecting');
            addStatusMessage('info', 'Connecting to browser stream');

            const streamId = sessionId || `stream-${Date.now()}`;
            const version = Date.now();
            const streamUrl = getApiUrl(`/browser-stream/${streamId}?_t=${version}`);

            eventSourceRef.current = new EventSource(streamUrl);

            // Stream connection opened
            eventSourceRef.current.onopen = () => {
                console.log('Stream connected');
                setStreamStatus('connected');
                addStatusMessage('success', 'Browser stream connected - Test is now running');
            };

            // Receiving stream data (images)
            eventSourceRef.current.onmessage = (event) => {
                if (event && event.data && event.data.startsWith('data:image')) {
                    const imageUrl = event.data.includes('#t=') ?
                        event.data :
                        `${event.data}#t=${Date.now()}`;

                    setBrowserImage(imageUrl);
                }
            };

            // Error handling
            eventSourceRef.current.onerror = (error) => {
                console.error('Stream error:', error);
                addStatusMessage('error', 'Stream connection error');
                stopStream();
            };

            // Custom status events from server
            eventSourceRef.current.addEventListener('status', (event) => {
                try {
                    const statusData = JSON.parse(event.data);
                    addStatusMessage(
                        statusData.type || 'stream',
                        statusData.message || `Stream ${statusData.type || 'event'}`
                    );

                    if (statusData.type === 'connected') {
                        setStreamStatus('connected');
                    } else if (statusData.type === 'error') {
                        setStreamStatus('error');
                    } else if (statusData.type === 'disconnected') {
                        setStreamStatus('disconnected');
                        stopStream();
                    }
                } catch (error) {
                    console.error('Error parsing status event:', error);
                }
            });
        } catch (error) {
            console.error('Error starting stream:', error);
            addStatusMessage('error', `Error starting stream: ${error.message}`);
            setStreaming(false);
            setStreamStatus('error');
        }
    };

    // Stop browser stream
    const stopStream = () => {
        if (!eventSourceRef.current) return;

        try {
            console.log('Stopping stream');

            // Notify server about disconnection
            if (socketRef.current && socketRef.current.connected) {
                socketRef.current.emit('stream-disconnect', {
                    sessionId: sessionId || `stream-${Date.now()}`,
                    timestamp: Date.now()
                });
            }

            // Close EventSource connection
            eventSourceRef.current.close();
            eventSourceRef.current = null;

            setStreaming(false);
            setStreamStatus('disconnected');
            addStatusMessage('stream', 'Stream stopped');
        } catch (error) {
            console.error('Error stopping stream:', error);
            eventSourceRef.current = null;
            setStreaming(false);
            setStreamStatus('error');
        }
    };

    // Request a screenshot
    const requestScreenshot = async () => {
        try {
            console.log("Requesting screenshot...");
            const apiUrl = getApiUrl('/screenshot');
            await axios.get(apiUrl);
            return true;
        } catch (err) {
            console.error("Error requesting screenshot:", err);
            return false;
        }
    };

    // Toggle preview display
    const togglePreview = () => {
        setPreviewVisible(!previewVisible);

        // If hiding preview while streaming, stop the stream
        if (previewVisible && streaming) {
            stopStream();
        }
    };

    // Add a timeout to automatically end loading state after a reasonable time
    useEffect(() => {
        let loadingTimeout;

        if (loading) {
            // Set a timeout to end loading state after 30 seconds as a fallback
            loadingTimeout = setTimeout(() => {
                console.log('Loading timeout reached, forcing completion');
                setLoading(false);
                addStatusMessage('warning', 'Response timed out, but processing may continue in background');

                // Take a screenshot to show current state
                requestScreenshot();
            }, 30000); // 30 seconds timeout
        }

        return () => {
            if (loadingTimeout) clearTimeout(loadingTimeout);
        };
    }, [loading, addStatusMessage, requestScreenshot]);

    // Add a manual way to cancel loading if needed
    const cancelLoading = () => {
        if (loading) {
            setLoading(false);
            addStatusMessage('warning', 'Loading cancelled by user');

            // Take a screenshot to show current state
            requestScreenshot();
        }
    };

    // Add an event handler for navigation completion
    useEffect(() => {
        // Store a reference to the current socket for cleanup
        const currentSocket = socketRef.current;

        // Only add the event listener if socket exists
        if (currentSocket) {
            const handleNavigationComplete = (data) => {
                console.log('Navigation complete:', data);
                addStatusMessage('success', `Navigated to: ${data.url || 'website'}`);

                // End loading state if we were waiting for navigation
                if (loading && messages.some(m =>
                    m.role === 'user' &&
                    m.content.toLowerCase().includes('navigate')
                )) {
                    setLoading(false);
                }

                // Take a screenshot to show the navigated page
                requestScreenshot();
            };

            // Add the event listener
            currentSocket.on('navigation-complete', handleNavigationComplete);

            // Cleanup function that uses the captured socket reference
            return () => {
                try {
                    if (currentSocket) {
                        currentSocket.off('navigation-complete', handleNavigationComplete);
                    }
                } catch (err) {
                    console.warn('Error removing navigation event listener:', err);
                }
            };
        }

        // Return empty cleanup if no socket exists
        return () => { };
    }, [socketRef, loading, messages, addStatusMessage, requestScreenshot]);

    // Add a function to try direct API call as a last resort
    const tryDirectApiCall = async () => {
        try {
            console.log("Trying direct API call to the server as last resort...");
            addStatusMessage('warning', 'Trying direct connection to server as last resort');

            // Use a longer timeout for this request (10 seconds)
            const directUrl = 'http://localhost:3001/session';
            const response = await axios.post(directUrl, {}, { timeout: 10000 });

            if (response.data.success) {
                const newSessionId = response.data.sessionId;
                setSessionId(newSessionId);
                addStatusMessage('system', `Session initialized via direct connection: ${newSessionId}`);

                // Use direct URL for future API calls
                window.USE_DIRECT_API = true;
            }
        } catch (err) {
            console.error("All connection attempts failed:", err);
            setError(`Connection failed: Server may not be running. Please run 'bash ./start-all.sh' to start the server.`);
        }
    };

    // Helper function to get the appropriate API URL (with or without proxy)
    const getApiUrl = (path) => {
        // Always use direct connection for consistency
        return `http://localhost:3001${path.startsWith('/') ? path : `/${path}`}`;
    };

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>OpenAI MCP Client</h1>
                <button
                    className="toggle-preview-button"
                    onClick={togglePreview}
                >
                    {previewVisible ? 'Hide Preview' : 'Show Preview'}
                </button>
            </header>

            <main className="main-content">
                <div className="chat-section">
                    <div className="chat-header">
                        <h2>Chat</h2>
                        <button
                            className="toggle-technical-button"
                            onClick={toggleTechnicalMessages}
                            title={showTechnicalMessages ? 'Hide technical details' : 'Show technical details'}
                        >
                            {showTechnicalMessages ? 'Hide Technical Details' : 'Show Technical Details'}
                        </button>
                    </div>
                    <div className="chat-container">
                        {messages
                            .filter(msg =>
                                ['user', 'assistant'].includes(msg.role) ||
                                (showTechnicalMessages && ['tool', 'system', 'function'].includes(msg.role))
                            )
                            .map((message, index) => (
                                <div key={index} className={`message ${message.role}`}>
                                    <div className="message-role">{message.role === 'function' ? 'tool-result' : message.role}</div>
                                    <div className="message-content">
                                        {message.role === 'function' || message.role === 'tool' ? (
                                            <pre className="tool-content">{typeof message.content === 'string' ? message.content : JSON.stringify(message.content, null, 2)}</pre>
                                        ) : (
                                            <div>{message.content}</div>
                                        )}
                                        {message.tool_calls && (
                                            <div className="tool-calls">
                                                <div className="tool-call-header">Tool Calls:</div>
                                                {message.tool_calls.map((tool, toolIndex) => (
                                                    <div key={toolIndex} className="tool-call">
                                                        <div className="tool-name">{tool.function?.name || 'Unknown Tool'}</div>
                                                        <pre className="tool-args">{tool.function?.arguments || '{}'}</pre>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        {error && (
                            <div className="message error">
                                <div className="message-role">Error</div>
                                <div className="message-content">{error}</div>
                            </div>
                        )}
                        {loading && (
                            <div className="message loading">
                                <div className="message-content">
                                    <div className="loading-spinner"></div>
                                    <button
                                        className="cancel-loading-button"
                                        onClick={cancelLoading}
                                        title="Cancel loading"
                                    >
                                        Cancel
                                    </button>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    <form className="input-container" onSubmit={handleSendMessage}>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            placeholder="Type your message..."
                            className="message-input"
                            disabled={loading || !sessionId}
                        />
                        <button
                            type="submit"
                            className="send-button"
                            disabled={loading || !sessionId || !inputValue.trim()}
                        >
                            Send
                        </button>
                    </form>
                </div>

                {previewVisible && (
                    <div className="preview-section">
                        <h2 className="preview-title">
                            Browser Preview
                            <div className="preview-controls">
                                {streaming ? (
                                    <button
                                        onClick={stopStream}
                                        className="stream-button stop"
                                        disabled={!sessionId}
                                    >
                                        Stop Stream
                                    </button>
                                ) : (
                                    <button
                                        onClick={startStream}
                                        className="stream-button start"
                                        disabled={!sessionId}
                                    >
                                        Start Stream
                                    </button>
                                )}
                                <button
                                    onClick={requestScreenshot}
                                    className="refresh-preview-button"
                                    disabled={!sessionId || streaming}
                                >
                                    Take Screenshot
                                </button>
                            </div>
                        </h2>
                        <div className={`stream-status ${streamStatus} ${streaming ? 'pulsing' : ''}`}>
                            {streamStatus === 'waiting' ? 'Test starting...' :
                                streamStatus === 'connecting' ? 'Connecting...' :
                                    streamStatus === 'connected' ? 'Test running' :
                                        streamStatus.charAt(0).toUpperCase() + streamStatus.slice(1)}
                        </div>
                        <div className="browser-preview">
                            {browserImage ? (
                                <img
                                    src={browserImage}
                                    alt="Browser preview"
                                    className="browser-image"
                                    title={streaming ? "Live stream" : "Static screenshot"}
                                />
                            ) : (
                                <div className="no-preview">
                                    No browser activity yet
                                </div>
                            )}
                        </div>

                        <div className="status-log">
                            <h3>Status Log</h3>
                            <div className="status-messages">
                                {statusMessages.length === 0 ? (
                                    <div className="status-message info">
                                        <span className="status-time">--:--:--</span>
                                        <span className="status-text">Waiting for activity...</span>
                                    </div>
                                ) : (
                                    statusMessages.map((status, index) => (
                                        <div key={index} className={`status-message ${status.type}`}>
                                            <span className="status-time">{status.time}</span>
                                            <span className="status-text">{status.text}</span>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
